function hydrate(){$$("[data-hyd]:not([data-done])").forEach(function(el){el.dataset.done=1;var cfg=cfgOf(el),t=el.dataset.hyd;
 if(t==="cur")conv(el);
 else if(t==="map"){var q=cfg.query,p=GEO[q];var put=function(p){var b=$(".xw-mapb",el);if(b)b.innerHTML=p?mapInner(cfg,p):'<div class="xw-load">Location not found</div>'};if(p!==undefined)return put(p);fetch("https://nominatim.openstreetmap.org/search?format=json&limit=1&q="+encodeURIComponent(q)).then(function(r){return r.json()}).then(function(j){GEO[q]=j[0]?{lat:+j[0].lat,lng:+j[0].lon}:null;put(GEO[q])}).catch(function(){put(null)})}
 else if(t==="weather"){var name=cfg.location||cfg.city||"",key="w:"+name+cfg.lat+cfg.lng,show=function(w){el.innerHTML=w?w.html:'<div class="xw-load">Weather unavailable</div>'};if(GEO[key]!==undefined)return show(GEO[key]);
  var go=function(lat,lng,label){var f=/^f/i.test(cfg.unit||"");fetch("https://api.open-meteo.com/v1/forecast?latitude="+lat+"&longitude="+lng+"&current=temperature_2m,apparent_temperature,relative_humidity_2m,weather_code,wind_speed_10m&daily=weather_code,temperature_2m_max,temperature_2m_min&timezone=auto&forecast_days=5"+(f?"&temperature_unit=fahrenheit&wind_speed_unit=mph":"")).then(function(r){return r.json()}).then(function(j){var c=j.current,w=wxi(c.weather_code),u=f?"°F":"°C";
   var days=j.daily.time.map(function(d,i){var x=wxi(j.daily.weather_code[i]);return'<div><small>'+new Date(d).toLocaleDateString(undefined,{weekday:"short"})+'</small><span>'+x[1]+'</span><b>'+Math.round(j.daily.temperature_2m_max[i])+'°</b><small>'+Math.round(j.daily.temperature_2m_min[i])+'°</small></div>'}).join("");
   GEO[key]={html:'<div class="xw-wxm"><div><small>'+E(label)+'</small><div class="xw-wxt">'+Math.round(c.temperature_2m)+u+'</div><small>'+w[0]+' · feels '+Math.round(c.apparent_temperature)+'°</small></div><div class="xw-wxi">'+w[1]+'</div></div><div class="xw-wxs"><span>💧 '+c.relative_humidity_2m+'%</span><span>💨 '+Math.round(c.wind_speed_10m)+(f?" mph":" km/h")+'</span></div><div class="xw-wxd">'+days+'</div>'};show(GEO[key])}).catch(function(){show(null)})};
  if(cfg.lat!=null&&cfg.lng!=null)go(cfg.lat,cfg.lng,name||"Weather");else fetch("https://geocoding-api.open-meteo.com/v1/search?count=1&name="+encodeURIComponent(name)).then(function(r){return r.json()}).then(function(j){var r=j.results&&j.results[0];if(!r){GEO[key]=null;return show(null)}go(r.latitude,r.longitude,r.name+(r.country?", "+r.country:""))}).catch(function(){show(null)})}})}
