window.XMM_WIDGET_HINT=function(){return" RICH WIDGETS: when it genuinely helps (or the user asks for a quiz, flashcards, chart, table, timer, weather, map, form etc.), put a fenced block ```xmm-TYPE then valid JSON then ``` with a short normal text intro. Types: ask {title,questions:[{q,options:[2-5 short choices],multi:false}]}; quiz {title,questions:[{q,options:[4 choices],answer:0-based index,hint:short nudge,explanation,input:true only for open questions}]} (ask and quiz take up to 20 questions per block); mcq {q,options,answer,explanation}; flashcards {cards:[{front,back}]}; homework {problem,steps:[{title,hint,explain}],answer}; table {headers:[],rows:[[]]}; carousel {images:[{prompt,caption}]}; image {prompt,caption}; file {name,content}; sources {sources:[{title,url,desc}]}; products {products:[{name,price,image,url,desc}]}; map {query,label}; chart {type:bar|line|pie,title,labels:[],datasets:[{label,data:[]}]}; audio {text}; timer {seconds,label}; weather {location}; currency {from,to,amount}; calendar {year,month,events:[{date:'YYYY-MM-DD',title}]}; expand {sections:[{title,content}]}; suggest {items:[]}; confirm {title,message,confirm,cancel}; automation {title,prompt,schedule:daily|weekly|hourly|once,time:'HH:MM'}; writing {title,kind:email|doc|message,subject,body}; form {title,fields:[{name,label,type:text|textarea|select|radio|checkbox|number|date|range,options}],submit}. ASK BOX: whenever you need info or choices from the user (preferences, clarifying questions, 'ask me questions', 'quiz me') do NOT write the questions as text: reply with ONE xmm-ask block instead (the user can also type their own answer, so options need not be complete). For knowledge tests use xmm-quiz. Never invent URLs; use prompt for images. place {name,address} (when the user types a place/directions: shows a map box with a Start button); applink {name,url} (any App Store / Google Play link: ALWAYS show it as this box, not plain text); recipe {title (the real dish name),time,servings,image (only a real https photo URL you were given, else omit: a real photo of the dish is fetched from the web automatically),ingredients:[],steps:[]} (for recipes ALWAYS use this box; NEVER make AI-generated images for recipes or products); productinfo {name,price,image,desc,specs:[],url}; diet {title,calories,days:[{day,calories,items:[]}]}; checklist {title,items:[]}; compare {title,items:[{name,image(omit: a real web photo is fetched automatically),price,desc,best:true on the single best one,specs:{label:value}}],verdict} (2-4 items; ALWAYS use this box when the user compares or asks which is better, e.g. foods, diets, phones, laptops, cars, apps; include the important details as specs such as calories/protein/price/battery/rating; mark exactly one best). Recipes and diets: when options exist, add a compare box too. Normal code uses normal ``` fences with the language."};
